import { createServer } from 'node:http'
import { after, afterEach, before, describe, it } from 'node:test'
import assert from 'node:assert/strict'
import { http, HttpResponse, passthrough } from 'msw'
import { setupServer } from 'msw/node'
import { createApp } from '../src/app.mjs'
import { createPricingClient } from '../src/pricing-client.mjs'

const prices = { 'sku-a': 10, 'sku-b': 25, cheap: 0.1, odd: 19.99, penny: 33.34 }
const pricingApi = 'http://pricing.test'
const pricingHandler = http.get(`${pricingApi}/prices/:sku`, ({ params }) => HttpResponse.json({ price: prices[params.sku] }))
const msw = setupServer(pricingHandler, http.all('http://127.0.0.1:*/*', () => passthrough()))

let server, base
