  msw.listen({ onUnhandledFrame: 'error' })
  server = createServer(createApp({ pricing: createPricingClient(pricingApi) }))
  await new Promise((r) => server.listen(0, '127.0.0.1', r))
  base = `http://127.0.0.1:${server.address().port}`
})
