  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

describe('POST /orders totals', () => {
  it('returns 201 with id, items and total', async () => {
    const res = await post({ items: [{ sku: 'sku-a', qty: 2 }] })
    assert.equal(res.status, 201)
    assert.equal(res.headers.get('content-type'), 'application/json')
    const body = await res.json()
    assert.equal(typeof body.id, 'string')
    assert.deepEqual(body.items, [{ sku: 'sku-a', qty: 2 }])
    assert.equal(body.total, 20)
  })

  it('sums several lines', async () => {
    assert.equal(await totalOf([{ sku: 'sku-a', qty: 2 }, { sku: 'sku-b', qty: 3 }]), 95)
  })

  it('applies no discount at exactly 100', async () => {
    assert.equal(await totalOf([{ sku: 'sku-a', qty: 10 }]), 100)
  })

  it('applies 10% discount above 100 (110 -> 99)', async () => {
    assert.equal(await totalOf([{ sku: 'sku-a', qty: 11 }]), 99)
  })

  it('discounts a larger order (500 -> 450)', async () => {
    assert.equal(await totalOf([{ sku: 'sku-b', qty: 20 }]), 450)
  })

  // CHARACTERIZATION: current behaviour may be unintended — discount cliff: 100 pays 100, 101 pays 90 (total drops as the order grows)
  it('charges less for 101 than for 100', async () => {
    assert.equal(await totalOf([{ sku: 'sku-a', qty: 10 }, { sku: 'cheap', qty: 10 }]), 90) // 101 -> 90.9 -> 90
  })

  // CHARACTERIZATION: current behaviour may be unintended — total is Math.floor'd to whole euros, cents are dropped (and floor is applied after discount)
  it('truncates cents instead of rounding', async () => {
    assert.equal(await totalOf([{ sku: 'odd', qty: 1 }]), 19) // 19.99
    assert.equal(await totalOf([{ sku: 'penny', qty: 3 }]), 90) // 100.02 -> 90.018 -> 90
  })

  // CHARACTERIZATION: current behaviour may be unintended — total is a whole number, so the response has no cents
  it('floors a discounted total (105 -> 94.5 -> 94)', async () => {
    assert.equal(await totalOf([{ sku: 'sku-a', qty: 10 }, { sku: 'cheap', qty: 50 }]), 94 + 0 * 1 || 94)
  })

  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated; zero/negative quantities are accepted
  it('accepts negative qty and yields a negative total', async () => {
    assert.equal(await totalOf([{ sku: 'sku-a', qty: -1 }]), -10)
  })

  // CHARACTERIZATION: current behaviour may be unintended — unknown sku (price undefined) gives NaN, serialised as null
  it('yields null total for an unknown sku', async () => {
    assert.equal(await totalOf([{ sku: 'nope', qty: 1 }]), null)
  })

  it('assigns increasing ids', async () => {
    const a = await (await post({ items: [{ sku: 'sku-a', qty: 1 }] })).json()
    const b = await (await post({ items: [{ sku: 'sku-a', qty: 1 }] })).json()
    assert.equal(Number(b.id), Number(a.id) + 1)
  })
})

describe('POST /orders validation', () => {
  for (const [name, body, raw] of [['missing items', {}], ['empty items', { items: [] }], ['items not array', { items: 'x' }], ['invalid json', null, '{nope']]) {
    it(`400 on ${name}`, async () => {
      const res = await post(body, raw)
      assert.equal(res.status, 400)
      assert.deepEqual(await res.json(), { error: 'items required' })
    })
  }
})

describe('GET /orders/:id', () => {
  it('returns a stored order', async () => {
    const created = await (await post({ items: [{ sku: 'sku-b', qty: 1 }] })).json()
    const res = await fetch(`${base}/orders/${created.id}`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), created)
  })

  // CHARACTERIZATION: current behaviour may be unintended — unknown order returns status 200, not 404
  it('returns 200 with an error body for an unknown order', async () => {
    const res = await fetch(`${base}/orders/does-not-exist`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), { error: 'not found' })
  })
})

describe('unknown routes', () => {
  it('404 for unknown path', async () => {
    const res = await fetch(`${base}/nope`)
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  })
  it('404 for wrong method on /orders/:id and /orders', async () => {
    assert.equal((await fetch(`${base}/orders`)).status, 404)
    assert.equal((await fetch(`${base}/orders/1`, { method: 'DELETE' })).status, 404)
  })
})
